-- ADR-0048 (PLAN.md Round E24) — 공식 7개 시나리오를 미션 콘텐츠와 함께 v2로 한 번에 올린다.
-- v1은 그대로 둔다(진행 중·완료 세션과 v1 토론은 v1에 묶여 남는다). 새 세션은 최신 PUBLISHED인 v2를 고른다.
-- INITIAL 프롬프트는 요구사항 질의(M1)를 위해 일부러 줄였다 — 빠진 수치는 clarifications의 답(requirementKey로
-- 공개 개요에서도 숨김)에 있다. FOLLOWUP 변형은 v1 문구 그대로에 M7 breaks만 더했고, INCIDENT·버전 규칙은 v1에서 복사한다.

-- coupon
insert into scenario_versions (id, scenario_id, version_no, status, followup_rules, incident_rules) select 'a0000000-0000-0000-0000-000000000020', scenario_id, 2, 'PUBLISHED', followup_rules, incident_rules from scenario_versions where id = 'a0000000-0000-0000-0000-000000000003';
insert into scenario_steps (scenario_version_id, step_order, step_type, trigger_condition, content) values ('a0000000-0000-0000-0000-000000000020', 1, 'INITIAL', null, '{"prompt": "선착순 쿠폰 발급 시스템을 설계하세요. 이벤트가 시작되는 순간 많은 사용자가 동시에 몰립니다.", "clarifications": [{"id": "users", "question": "이벤트 시작 직후 몇 명 정도가 몰리나요?", "answer": "약 100만 명이 이벤트 시작 직후 접속합니다.", "critical": true, "requirementKey": "targetUsers"}, {"id": "total", "question": "쿠폰은 몇 장인가요?", "answer": "1만 장입니다.", "critical": true, "requirementKey": "totalCoupons"}, {"id": "dup", "question": "한 사용자가 여러 장 받을 수 있나요?", "answer": "1인 1장입니다. 중복 발급은 절대 허용되지 않습니다.", "critical": true, "requirementKey": "duplicateIssueAllowed"}, {"id": "response", "question": "발급 결과를 나중에 알려줘도 되나요?", "answer": "아니요. 사용자는 요청 즉시 성공 또는 실패 응답을 받아야 합니다.", "critical": true, "requirementKey": "responseMode"}, {"id": "expiry", "question": "쿠폰 유효기간은 얼마인가요?", "answer": "발급 후 7일입니다. 설계에 큰 영향은 없습니다.", "critical": false}, {"id": "button", "question": "발급 버튼 디자인은 정해졌나요?", "answer": "디자인팀 소관입니다.", "critical": false}], "estimation": [{"key": "peakRps", "label": "피크 발급 요청", "unit": "req/s", "answer": 100000, "hint": "100만 명이 첫 10초 안에 한 번씩 누른다면?"}, {"key": "successWrites", "label": "성공 발급 확정 쓰기 총량", "unit": "건", "answer": 10000, "hint": "성공할 수 있는 요청은 몇 건인가?"}], "assumptions": [{"id": "traffic-estimate", "text": "트래픽은 예상치(약 100만 명)를 넘지 않는다"}, {"id": "one-device", "text": "사용자는 한 기기에서 한 번만 요청한다"}, {"id": "redis-available", "text": "Redis는 장애 없이 동작한다"}, {"id": "single-region", "text": "단일 리전에서 운영한다"}], "constraints": {"budgetPerMonth": 3000, "teamSize": 3, "opsExperience": {"cache": "HIGH", "db": "MEDIUM", "queue": "LOW"}}}'::jsonb);
insert into scenario_steps (scenario_version_id, step_order, step_type, trigger_condition, content)
select 'a0000000-0000-0000-0000-000000000020', step_order, step_type, trigger_condition,
       jsonb_build_object('variants', (select jsonb_agg(v || jsonb_build_object('breaks', coalesce('{"traffic-spike": ["traffic-estimate"], "duplicate-issue-spike": ["one-device"], "bot-traffic": ["traffic-estimate", "one-device"]}'::jsonb -> (v->>'key'), '[]'::jsonb)) order by ord)
                                       from jsonb_array_elements(content->'variants') with ordinality as t(v, ord)))
from scenario_steps where scenario_version_id = 'a0000000-0000-0000-0000-000000000003' and step_type = 'FOLLOWUP';
insert into scenario_steps (scenario_version_id, step_order, step_type, trigger_condition, content) select 'a0000000-0000-0000-0000-000000000020', step_order, step_type, trigger_condition, content from scenario_steps where scenario_version_id = 'a0000000-0000-0000-0000-000000000003' and step_type = 'INCIDENT';

-- notification
insert into scenario_versions (id, scenario_id, version_no, status, followup_rules, incident_rules) select 'c0000000-0000-0000-0000-000000000020', scenario_id, 2, 'PUBLISHED', followup_rules, incident_rules from scenario_versions where id = 'c0000000-0000-0000-0000-000000000003';
insert into scenario_steps (scenario_version_id, step_order, step_type, trigger_condition, content) values ('c0000000-0000-0000-0000-000000000020', 1, 'INITIAL', null, '{"prompt": "주문·결제·배송 이벤트가 발생할 때마다 사용자에게 알림을 보내는 시스템을 설계하세요.", "clarifications": [{"id": "channels", "question": "어떤 채널로 보내나요?", "answer": "이메일·푸시·SMS 세 가지이며, 각각 외부 provider를 씁니다.", "critical": true}, {"id": "timing", "question": "알림이 이벤트와 동시에 가야 하나요?", "answer": "아니요. 비동기로 보내도 되지만 최종적으로는 반드시 전달돼야 합니다.", "critical": true, "requirementKey": "deliveryMode"}, {"id": "volume", "question": "이벤트는 초당 몇 건인가요?", "answer": "평시 초당 50건입니다.", "critical": true, "requirementKey": "eventsPerSecond"}, {"id": "dup", "question": "같은 알림이 두 번 가도 되나요?", "answer": "안 됩니다. 특히 결제 완료 알림의 중복은 바로 민원이 됩니다.", "critical": true, "requirementKey": "duplicateDeliveryAllowed"}, {"id": "template", "question": "알림 문구는 누가 관리하나요?", "answer": "마케팅팀이 관리합니다(설계 범위 밖).", "critical": false}], "estimation": [{"key": "dailyMessages", "label": "하루 발송 메시지 수(이벤트당 1건)", "unit": "건", "answer": 4320000, "hint": "초당 50건 × 하루"}, {"key": "concurrentCalls", "label": "provider 응답이 3초일 때 초당 50건을 처리하는 데 필요한 동시 호출 수", "unit": "개", "answer": 150, "hint": "동시에 처리 중인 수 = 처리율 × 처리 시간"}], "assumptions": [{"id": "provider-fast", "text": "외부 provider는 200ms 안에 응답한다"}, {"id": "steady", "text": "이벤트는 하루 내내 고르게 들어온다"}, {"id": "well-formed", "text": "이벤트 데이터 형식은 항상 올바르다"}, {"id": "no-order", "text": "알림 순서 보장은 필요 없다"}], "constraints": {"budgetPerMonth": 2000, "teamSize": 2, "opsExperience": {"queue": "MEDIUM", "cache": "LOW"}}}'::jsonb);
insert into scenario_steps (scenario_version_id, step_order, step_type, trigger_condition, content)
select 'c0000000-0000-0000-0000-000000000020', step_order, step_type, trigger_condition,
       jsonb_build_object('variants', (select jsonb_agg(v || jsonb_build_object('breaks', coalesce('{"volume-spike": ["steady"], "malformed-events": ["well-formed"], "provider-degradation": ["provider-fast"]}'::jsonb -> (v->>'key'), '[]'::jsonb)) order by ord)
                                       from jsonb_array_elements(content->'variants') with ordinality as t(v, ord)))
from scenario_steps where scenario_version_id = 'c0000000-0000-0000-0000-000000000003' and step_type = 'FOLLOWUP';
insert into scenario_steps (scenario_version_id, step_order, step_type, trigger_condition, content) select 'c0000000-0000-0000-0000-000000000020', step_order, step_type, trigger_condition, content from scenario_steps where scenario_version_id = 'c0000000-0000-0000-0000-000000000003' and step_type = 'INCIDENT';

-- product-browsing
insert into scenario_versions (id, scenario_id, version_no, status, followup_rules, incident_rules) select 'd0000000-0000-0000-0000-000000000020', scenario_id, 2, 'PUBLISHED', followup_rules, incident_rules from scenario_versions where id = 'd0000000-0000-0000-0000-000000000003';
insert into scenario_steps (scenario_version_id, step_order, step_type, trigger_condition, content) values ('d0000000-0000-0000-0000-000000000020', 1, 'INITIAL', null, '{"prompt": "상품 상세 페이지에서 가격·재고·리뷰를 함께 보여주는 조회 시스템을 설계하세요.", "clarifications": [{"id": "traffic", "question": "평시 트래픽은 얼마인가요?", "answer": "초당 500건 정도입니다.", "critical": true, "requirementKey": "baselineRps"}, {"id": "price", "question": "가격이 잠깐이라도 이전 값이면 안 되나요?", "answer": "가격은 항상 최신이어야 합니다. 결제 금액과 달라지면 안 됩니다.", "critical": true, "requirementKey": "priceFreshnessRequired"}, {"id": "review", "question": "리뷰도 실시간이어야 하나요?", "answer": "리뷰는 몇 분 늦게 보여도 괜찮습니다.", "critical": true, "requirementKey": "reviewStaleAllowed"}, {"id": "writes", "question": "상품 정보는 얼마나 자주 바뀌나요?", "answer": "가격·재고는 하루 수십 번, 리뷰는 꾸준히 추가됩니다. 읽기가 압도적으로 많습니다.", "critical": false}, {"id": "images", "question": "상품 이미지는 어떻게 하나요?", "answer": "CDN이 이미 있습니다(설계 범위 밖).", "critical": false}], "estimation": [{"key": "peakRps", "label": "피크(평시의 20배) 조회 요청", "unit": "req/s", "answer": 10000}, {"key": "dbReads", "label": "캐시 적중률 90%일 때 피크에 DB로 가는 읽기", "unit": "req/s", "answer": 1000, "hint": "miss 비율 × 피크 요청"}], "assumptions": [{"id": "uniform", "text": "요청이 상품 전체에 고르게 퍼진다"}, {"id": "read-flat", "text": "읽기 트래픽은 크게 늘지 않는다"}, {"id": "same-ttl", "text": "가격·재고·리뷰를 같은 캐시 정책으로 다뤄도 된다"}, {"id": "single-db", "text": "DB 하나로 읽기를 감당할 수 있다"}], "constraints": {"budgetPerMonth": 2500, "teamSize": 3, "opsExperience": {"cache": "MEDIUM", "db": "HIGH", "cdn": "HIGH"}}}'::jsonb);
insert into scenario_steps (scenario_version_id, step_order, step_type, trigger_condition, content)
select 'd0000000-0000-0000-0000-000000000020', step_order, step_type, trigger_condition,
       jsonb_build_object('variants', (select jsonb_agg(v || jsonb_build_object('breaks', coalesce('{"traffic-spike": ["same-ttl", "single-db"], "flash-sale-hot-item": ["uniform"], "read-heavy-growth": ["read-flat", "single-db"]}'::jsonb -> (v->>'key'), '[]'::jsonb)) order by ord)
                                       from jsonb_array_elements(content->'variants') with ordinality as t(v, ord)))
from scenario_steps where scenario_version_id = 'd0000000-0000-0000-0000-000000000003' and step_type = 'FOLLOWUP';
