insert into scenario_versions (id, scenario_id, version_no, status, followup_rules, incident_rules) select 'b1000000-0000-0000-0000-000000000020', scenario_id, 2, 'PUBLISHED', followup_rules, incident_rules from scenario_versions where id = 'b1000000-0000-0000-0000-000000000003';
insert into scenario_steps (scenario_version_id, step_order, step_type, trigger_condition, content) values ('b1000000-0000-0000-0000-000000000020', 1, 'INITIAL', null, '{"prompt": "사용자가 상품을 주문하고 결제하는 시스템을 설계하세요. 외부 결제대행사(PG)와 연동합니다.", "clarifications": [{"id": "consistency", "question": "주문과 결제 상태가 잠깐 달라도 되나요?", "answer": "최종적으로 일치하면 되지만, 결제 금액은 반드시 정확해야 합니다.", "critical": true, "requirementKey": "consistencyMode"}, {"id": "dup", "question": "같은 결제가 두 번 될 수 있나요?", "answer": "절대 안 됩니다. 이중 결제는 환불·CS 비용으로 바로 이어집니다.", "critical": true, "requirementKey": "duplicateChargeAllowed"}, {"id": "rps", "question": "주문은 초당 몇 건인가요?", "answer": "평시 초당 30건입니다.", "critical": true, "requirementKey": "baselineOrderRps"}, {"id": "pg", "question": "PG 응답 시간은 어느 정도인가요?", "answer": "보통 300ms지만 가끔 수 초까지 늘어납니다.", "critical": true}, {"id": "refund", "question": "환불도 설계 범위인가요?", "answer": "이번 범위는 주문과 결제까지입니다.", "critical": false}], "estimation": [{"key": "concurrentPg", "label": "PG 응답 3초일 때 초당 30건을 처리하려면 동시에 열려 있어야 하는 PG 호출 수", "unit": "개", "answer": 90, "hint": "동시에 처리 중인 수 = 처리율 × 처리 시간"}, {"key": "dailyOrders", "label": "하루 주문 수", "unit": "건", "answer": 2592000}], "assumptions": [{"id": "pg-fast", "text": "PG는 항상 1초 안에 응답한다"}, {"id": "response-arrives", "text": "PG 응답은 반드시 클라이언트에 도착한다"}, {"id": "one-tx", "text": "주문 저장과 결제를 하나의 트랜잭션으로 묶을 수 있다"}, {"id": "shared-pool", "text": "주문과 결제가 같은 DB 커넥션 풀을 써도 된다"}], "constraints": {"budgetPerMonth": 3000, "teamSize": 4, "opsExperience": {"db": "HIGH", "queue": "MEDIUM"}}}'::jsonb);
insert into scenario_steps (scenario_version_id, step_order, step_type, trigger_condition, content)
select 'b1000000-0000-0000-0000-000000000020', step_order, step_type, trigger_condition,
       jsonb_build_object('variants', (select jsonb_agg(v || jsonb_build_object('breaks', coalesce('{"pg-latency-spike": ["pg-fast", "shared-pool"], "lost-response": ["response-arrives"], "no-shared-transaction": ["one-tx"]}'::jsonb -> (v->>'key'), '[]'::jsonb)) order by ord)
                                       from jsonb_array_elements(content->'variants') with ordinality as t(v, ord)))
from scenario_steps where scenario_version_id = 'b1000000-0000-0000-0000-000000000003' and step_type = 'FOLLOWUP';
