insert into scenario_versions (id, scenario_id, version_no, status, followup_rules, incident_rules) select 'b2000000-0000-0000-0000-000000000020', scenario_id, 2, 'PUBLISHED', followup_rules, incident_rules from scenario_versions where id = 'b2000000-0000-0000-0000-000000000003';
insert into scenario_steps (scenario_version_id, step_order, step_type, trigger_condition, content) values ('b2000000-0000-0000-0000-000000000020', 1, 'INITIAL', null, '{"prompt": "인기 공연의 좌석 예약 시스템을 설계하세요.", "clarifications": [{"id": "dup", "question": "같은 좌석이 두 명에게 팔릴 수 있나요?", "answer": "절대 안 됩니다.", "critical": true, "requirementKey": "duplicateReservationAllowed"}, {"id": "consistency", "question": "예약 확정 여부를 나중에 알려줘도 되나요?", "answer": "좌석을 선택한 직후 확정 여부를 바로 보여줘야 합니다(강한 일관성).", "critical": true, "requirementKey": "consistencyMode"}, {"id": "rps", "question": "예약 시도는 초당 몇 건인가요?", "answer": "평시 초당 20건이고, 예약 오픈 직후에는 크게 늘어납니다.", "critical": true, "requirementKey": "baselineReservationRps"}, {"id": "hold", "question": "결제할 때까지 좌석을 잡아두나요?", "answer": "네. 좌석 선택부터 결제 완료까지 홀드합니다. 결제는 보통 3분 안에 끝납니다.", "critical": true}, {"id": "seats", "question": "공연당 좌석 수는?", "answer": "약 5,000석입니다.", "critical": false}], "estimation": [{"key": "openRps", "label": "예약 오픈 직후(평시의 15배) 예약 시도", "unit": "req/s", "answer": 300}, {"key": "heldSeats", "label": "평시 초당 20건이 모두 홀드에 성공하고 결제가 3분 걸릴 때 동시에 홀드된 좌석 수", "unit": "석", "answer": 3600, "hint": "동시에 처리 중인 수 = 처리율 × 처리 시간"}], "assumptions": [{"id": "everyone-pays", "text": "좌석을 고른 사용자는 대부분 결제를 끝낸다"}, {"id": "one-api", "text": "재고 확인과 예약 확정이 한 API 안에서 일어난다"}, {"id": "steady-load", "text": "예약 오픈 직후에도 시도량이 평시와 크게 다르지 않다"}, {"id": "coarse-lock-ok", "text": "공연 단위로 락을 잡아도 처리량이 충분하다"}], "constraints": {"budgetPerMonth": 2000, "teamSize": 2, "opsExperience": {"db": "HIGH", "cache": "MEDIUM"}}}'::jsonb);
