-- batch-settlement
insert into scenario_versions (id, scenario_id, version_no, status, followup_rules, incident_rules) select 'b3000000-0000-0000-0000-000000000020', scenario_id, 2, 'PUBLISHED', followup_rules, incident_rules from scenario_versions where id = 'b3000000-0000-0000-0000-000000000003';
insert into scenario_steps (scenario_version_id, step_order, step_type, trigger_condition, content) values ('b3000000-0000-0000-0000-000000000020', 1, 'INITIAL', null, '{"prompt": "매일 새벽 거래 내역을 정산하는 배치 시스템을 설계하세요.", "clarifications": [{"id": "volume", "question": "하루 정산 대상은 몇 건인가요?", "answer": "약 100만 건입니다.", "critical": true, "requirementKey": "totalRecords"}, {"id": "failure", "question": "정산 도중 실패하면 어떻게 하나요?", "answer": "중간에 실패할 수 있고, 다시 처리해도 결과가 한 번만 반영돼야 합니다.", "critical": true, "requirementKey": "consistencyMode"}, {"id": "dup", "question": "같은 레코드가 두 번 반영되면 안 되나요?", "answer": "절대 안 됩니다. 가맹점에 금액이 두 번 지급됩니다.", "critical": true, "requirementKey": "duplicateSettlementAllowed"}, {"id": "window", "question": "언제까지 끝나야 하나요?", "answer": "새벽 2시에 시작해 오전 6시 전에 끝나야 합니다.", "critical": true}, {"id": "api", "question": "외부 시스템을 호출하나요?", "answer": "레코드마다 가맹점 정산 API를 호출합니다. 평소 50ms가 걸립니다.", "critical": false}], "estimation": [{"key": "throughput", "label": "4시간 안에 100만 건을 끝내려면 필요한 처리량", "unit": "건/s", "answer": 70}, {"key": "sequentialMinutes", "label": "API(50ms)를 하나씩 순서대로 호출하면 걸리는 시간", "unit": "분", "answer": 833, "hint": "100만 × 50ms"}], "assumptions": [{"id": "no-crash", "text": "배치 서버는 실행 도중 재시작되지 않는다"}, {"id": "api-fast", "text": "정산 API는 항상 50ms 안에 응답한다"}, {"id": "run-once", "text": "각 레코드는 한 번만 처리된다"}, {"id": "fixed-volume", "text": "정산 대상 건수는 매일 비슷하다"}], "constraints": {"budgetPerMonth": 1500, "teamSize": 2, "opsExperience": {"db": "HIGH", "queue": "LOW"}}}'::jsonb);
insert into scenario_steps (scenario_version_id, step_order, step_type, trigger_condition, content)
select 'b3000000-0000-0000-0000-000000000020', step_order, step_type, trigger_condition,
       jsonb_build_object('variants', (select jsonb_agg(v || jsonb_build_object('breaks', coalesce('{"confirmed-scale": ["fixed-volume"], "mid-run-failure": ["no-crash"], "reprocess-duplicate-risk": ["run-once"]}'::jsonb -> (v->>'key'), '[]'::jsonb)) order by ord)
                                       from jsonb_array_elements(content->'variants') with ordinality as t(v, ord)))
from scenario_steps where scenario_version_id = 'b3000000-0000-0000-0000-000000000003' and step_type = 'FOLLOWUP';
insert into scenario_steps (scenario_version_id, step_order, step_type, trigger_condition, content) select 'b3000000-0000-0000-0000-000000000020', step_order, step_type, trigger_condition, content from scenario_steps where scenario_version_id = 'b3000000-0000-0000-0000-000000000003' and step_type = 'INCIDENT';

-- autoscaling
insert into scenario_versions (id, scenario_id, version_no, status, followup_rules, incident_rules) select 'b4000000-0000-0000-0000-000000000020', scenario_id, 2, 'PUBLISHED', followup_rules, incident_rules from scenario_versions where id = 'b4000000-0000-0000-0000-000000000003';
insert into scenario_steps (scenario_version_id, step_order, step_type, trigger_condition, content) values ('b4000000-0000-0000-0000-000000000020', 1, 'INITIAL', null, '{"prompt": "메인 화면에 노출되는 실시간 추천 API를 설계하세요. Kubernetes 위에서 운영합니다.", "clarifications": [{"id": "variance", "question": "트래픽 변동은 어느 정도인가요?", "answer": "시간대별로 크게 달라지고, 프로모션 때는 평시의 10배까지 튑니다.", "critical": true, "requirementKey": "trafficVariance"}, {"id": "deploy", "question": "배포는 어떻게 하나요?", "answer": "하루에도 여러 번 무중단 롤링 배포를 합니다.", "critical": true, "requirementKey": "deploymentModel"}, {"id": "baseline", "question": "평시 요청량과 Pod 처리량은?", "answer": "평시 초당 100건이고, Pod 하나가 초당 50건 정도를 처리합니다.", "critical": true}, {"id": "memory", "question": "Pod 메모리 사용량은?", "answer": "평시 300MB, 추천 모델 캐시를 올리면 700MB까지 늘어납니다.", "critical": true}, {"id": "model", "question": "추천 모델 학습도 설계하나요?", "answer": "범위 밖입니다. 학습된 모델을 받아서 씁니다.", "critical": false}], "estimation": [{"key": "peakPods", "label": "프로모션 피크(평시의 10배)에 필요한 Pod 수", "unit": "개", "answer": 20}, {"key": "peakMemoryGb", "label": "피크 Pod를 모두 띄울 때 필요한 메모리(모델 캐시 포함)", "unit": "GB", "answer": 14, "hint": "Pod 수 × Pod당 최대 메모리"}], "assumptions": [{"id": "stable-pods", "text": "Pod는 한번 뜨면 재시작 없이 안정적이다"}, {"id": "deploy-quiet", "text": "배포는 트래픽이 적을 때만 한다"}, {"id": "scale-enough", "text": "Pod만 늘리면 처리량이 늘어난다"}, {"id": "predictable-peak", "text": "트래픽 피크는 미리 예측할 수 있다"}], "constraints": {"budgetPerMonth": 2500, "teamSize": 3, "opsExperience": {"service": "MEDIUM", "gateway": "HIGH"}}}'::jsonb);
insert into scenario_steps (scenario_version_id, step_order, step_type, trigger_condition, content)
select 'b4000000-0000-0000-0000-000000000020', step_order, step_type, trigger_condition,
       jsonb_build_object('variants', (select jsonb_agg(v || jsonb_build_object('breaks', coalesce('{"confirmed-scale": ["predictable-peak", "scale-enough"], "resource-limit-incident": ["stable-pods"], "rollout-safety-incident": ["deploy-quiet"]}'::jsonb -> (v->>'key'), '[]'::jsonb)) order by ord)
                                       from jsonb_array_elements(content->'variants') with ordinality as t(v, ord)))
from scenario_steps where scenario_version_id = 'b4000000-0000-0000-0000-000000000003' and step_type = 'FOLLOWUP';
insert into scenario_steps (scenario_version_id, step_order, step_type, trigger_condition, content) select 'b4000000-0000-0000-0000-000000000020', step_order, step_type, trigger_condition, content from scenario_steps where scenario_version_id = 'b4000000-0000-0000-0000-000000000003' and step_type = 'INCIDENT';
